import hashlib, io, json, threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from provenance_api.app import application, reset_state

LAYER = b'live upstream layer bytes'
D = hashlib.sha256(LAYER).hexdigest()

class Up(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def do_GET(self):
        if self.path == f'/layers/{D}':
            self.send_response(200); self.send_header('Content-Length', str(len(LAYER))); self.end_headers(); self.wfile.write(LAYER)
        elif self.path == '/layers/'+('f'*64):
            self.send_response(404); self.end_headers()
        else:
            self.send_response(500); self.end_headers()

srv = HTTPServer(('127.0.0.1', 0), Up)
threading.Thread(target=srv.serve_forever, daemon=True).start()
port = srv.server_address[1]

reset_state()
env = {'REQUEST_METHOD':'POST','PATH_INFO':'/mirrors','wsgi.input': io.BytesIO(json.dumps({'name':'live','upstream':f'http://127.0.0.1:{port}/'}).encode()),'CONTENT_LENGTH':'9999','CONTENT_TYPE':'application/json'}
