print('register:', cap['s'])

def pull(digest):
    e={'REQUEST_METHOD':'POST','PATH_INFO':f'/mirrors/{mid}/pull/{digest}','wsgi.input':io.BytesIO(b''),'CONTENT_LENGTH':'0'}
